// ═══════════════════════════════════════════════════════════════════════
// Code Node: Finalize output
// Replaces: "Array to String"
// ═══════════════════════════════════════════════════════════════════════

// ─── HELPERS ────────────────────────────────────────────────────────────

function escapeRegex(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// ─── 1. EXTRACT INPUT ───────────────────────────────────────────────────

const llmOutput  = $input.first().json.output;
const profile    = llmOutput.candidate_profile;
const roleScores = llmOutput.role_type_scores;

const marketResearch = $('Detect CV Language').first().json.market_research || '';

// ─── 2. HOME CITY EDGE CASE ─────────────────────────────────────────────
// If market_research explicitly mentions the home city as a work location
// but the LLM omitted it from commute_options, prepend it.

const homeCity      = (profile.home_location || '').split(',')[0].trim();
let commuteOptions  = profile.commute_options || '';

if (homeCity) {
  const mentionedInMarket = new RegExp(
    '\\b' + escapeRegex(homeCity) + '\\b', 'i'
  ).test(marketResearch);

  const includedInCommute = new RegExp(
    '\\b' + escapeRegex(homeCity) + '\\b', 'i'
  ).test(commuteOptions);

  if (mentionedInMarket && !includedInCommute) {
    commuteOptions = `${homeCity} (~0h, home city) | ${commuteOptions}`;
  }
}

// ─── 3. OUTPUT ──────────────────────────────────────────────────────────

return [{
  json: {
    candidate_profile: {
      ...profile,
      commute_options: commuteOptions,
    },
    role_type_scores: JSON.stringify(roleScores),
  }
}];

const upstream = $input.first().json;
const cv_text = $input.first().json.cv_text;

function detectLanguage(text) {
  const input = String(text || "").trim();

  if (!input) {
    return {
      language: "unknown",
      confidence: 0,
      scores: { german: 0, english: 0 }
    };
  }

  const lower = input.toLowerCase();

  // Common markers
  const germanWords = [
    "der", "die", "das", "und", "ist", "nicht", "ich", "du", "wir", "ihr",
    "sie", "mit", "für", "auf", "ein", "eine", "einer", "einem", "den",
    "dem", "des", "wie", "was", "aber", "auch", "noch", "nur", "schon",
    "wenn", "dann", "oder", "hat", "haben", "war", "waren", "zum", "zur"
  ];

  const englishWords = [
    "the", "and", "is", "not", "i", "you", "we", "they", "with", "for",
    "on", "a", "an", "this", "that", "of", "to", "in", "as", "but",
    "also", "still", "only", "already", "if", "then", "or", "has", "have",
    "had", "was", "were", "be", "are", "from", "it"
  ];

  let germanScore = 0;
  let englishScore = 0;

  // Strong German hints
  if (/[äöüß]/.test(lower)) germanScore += 4;
  if (/\b(nicht|ich|und|für|mit|eine|einer|einem|der|die|das)\b/.test(lower)) germanScore += 3;
  if (/(sch|ung|keit|lich|chen)\b/.test(lower)) germanScore += 2;

  // Strong English hints
  if (/\b(the|and|with|this|that|have|from|are|was|were)\b/.test(lower)) englishScore += 3;
  if (/\b(ing|tion|ness|ment)\b/.test(lower)) englishScore += 1;

  // Count stopwords
  for (const word of germanWords) {
    const matches = lower.match(new RegExp(`\\b${word}\\b`, "g"));
    if (matches) germanScore += matches.length;
  }

  for (const word of englishWords) {
    const matches = lower.match(new RegExp(`\\b${word}\\b`, "g"));
    if (matches) englishScore += matches.length;
  }

  let language = "unknown";
  if (germanScore > englishScore) language = "de";
  else if (englishScore > germanScore) language = "en";

  const total = germanScore + englishScore;
  const confidence = total === 0
    ? 0
    : Number((Math.max(germanScore, englishScore) / total).toFixed(2));

  return {
    language,
    confidence,
    scores: {
      german: germanScore,
      english: englishScore
    }
  };
}

return [{
  ...upstream,
  cv_language: detectLanguage(cv_text)
}]

const rawExtraction = $('Raw Extraction - Market Research').first().json.output;
const coreSkillsRaw = $('Raw Extraction - Core Skills').first().json.output;
const decisions = $('Binary Classifier').first().json.output?.decisions ?? $input.first().json.decisions;

const CORE_SKILLS_THRESHOLD = 2; // change this to adjust

const technology_list = [
  ...new Set(
    decisions
      .filter(d => d.valid === true)
      .map(d => d.item)
  )
];

const city_list = rawExtraction?.city_list ?? [];
const role_list = JSON.stringify(rawExtraction?.role_list ?? []);

const skillCounts = coreSkillsRaw?.skill_counts ?? [];
const core_skills_list = JSON.stringify(
  skillCounts
    .filter(s => s.count >= CORE_SKILLS_THRESHOLD)
    .sort((a, b) => b.count - a.count)
    .map(s => s.technology)
);;

return [{ json: { technology_list, city_list, role_list, core_skills_list } }];
